    if (!columnId || !text) {
      return res.status(400).json({ error: 'columnId and text are required' });
    }

    // Start transaction
    await db.begin();

    try {
      // Get next position for the column
      const position = await getNextPosition(columnId);

      // Create the card
      const cardId = uuidv4();
      await db.sql`
        INSERT INTO cards (id, column_id, text, position)
        VALUES (${cardId}, ${columnId}, ${text}, ${position});
      `;

      // Commit transaction
      await db.commit();

      // Get the full column with the new card
      const column = await getColumnWithCards(columnId);

      // Broadcast the update
      broadcastEvent('card-created', { cardId, columnId, column });

      // Return the created card
      res.status(201).json({ id: cardId, columnId, text, position });
    } catch (error) {
      // Rollback transaction on error
      await db.rollback();
      throw error;
    }
  } catch (error) {
    console.error('Error creating card:', error);
    res.status(500).json({ error: 'Failed to create card' });
  }
});

// API endpoint to move a card
app.patch('/api/cards/:id/move', async (req, res) => {
  try {
    const cardId = req.params.id;
    const { columnId, beforeId, afterId } = req.body;

    if (!columnId) {
      return res.status(400).json({ error: 'columnId is required' });
    }

    // Start transaction to ensure atomic move
    await db.begin();

    try {
      // Get the current card
      const cardResult = await db.sql`
        SELECT column_id, position FROM cards WHERE id = ${cardId};
      `;

      if (cardResult.rows.length === 0) {
        await db.rollback();
        return res.status(404).json({ error: 'Card not found' });
      }

      const currentCard = cardResult.rows[0];

      // If moving to the same column and no position change, do nothing
      if (currentCard.column_id === columnId && (!beforeId && !afterId)) {
        await db.rollback();
        return res.json(currentCard);
      }

      let position;

      // Calculate new position
      if (beforeId && afterId) {
        // Between two cards
        const beforeResult = await db.sql`
          SELECT position FROM cards WHERE id = ${beforeId} AND column_id = ${columnId};
        `;
        const afterResult = await db.sql`
          SELECT position FROM cards WHERE id = ${afterId} AND column_id = ${columnId};
        `;

        if (beforeResult.rows.length === 0 || afterResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'Before or after card not found in target column' });
        }

        position = (beforeResult.rows[0].position + afterResult.rows[0].position) / 2;
      } else if (beforeId) {
        // Before a specific card
        const beforeResult = await db.sql`
          SELECT position FROM cards WHERE id = ${beforeId} AND column_id = ${columnId};
        `;

        if (beforeResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'Before card not found in target column' });
        }

        position = beforeResult.rows[0].position - 0.1;
      } else if (afterId) {
        // After a specific card
        const afterResult = await db.sql`
          SELECT position FROM cards WHERE id = ${afterId} AND column_id = ${columnId};
        `;

        if (afterResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'After card not found in target column' });
        }

        position = afterResult.rows[0].position + 0.1;
      } else {
        // End of the column
        position = await getNextPosition(columnId);
      }

      // Remove card from source column if different
      if (currentCard.column_id !== columnId) {
        await db.sql`
          DELETE FROM cards WHERE id = ${cardId};
        `;
      }

      // Add card to target column
      await db.sql`
        INSERT INTO cards (id, column_id, text, position)
        VALUES (${cardId}, ${columnId}, ${currentCard.text}, ${position})
        ON CONFLICT (id) DO UPDATE SET column_id = ${columnId}, position = ${position};
      `;

      // Commit transaction
      await db.commit();

      // Get the updated card
      const updatedCardResult = await db.sql`
        SELECT id, column_id, text, position FROM cards WHERE id = ${cardId};
      `;

      const updatedCard = updatedCardResult.rows[0];

      // Get the source and target columns to broadcast
      const sourceColumn = currentCard.column_id !== columnId 
        ? await getColumnWithCards(currentCard.column_id) 
        : null;

      const targetColumn = await getColumnWithCards(columnId);

      // Broadcast the move
      broadcastEvent('card-moved', { 
        cardId, 
        sourceColumnId: currentCard.column_id, 
        targetColumnId: columnId,
        sourceColumn,
        targetColumn
      });

      // Return the updated card
      res.json(updatedCard);
    } catch (error) {
      // Rollback transaction on error
      await db.rollback();
      throw error;
    }
