    }

    const column = getColumn(columnId);
    if (!column) {
      return res.status(404).json({ error: 'Column not found' });
    }

    // Get next position for the column
    const position = getNextPosition(columnId);

    // Create the card
    const cardId = uuidv4();
    const newCard = {
