    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position INTEGER NOT NULL DEFAULT 0
    );
  `;

  await db.sql`
    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id),
      text TEXT NOT NULL,
      position NUMERIC NOT NULL DEFAULT 0,
      created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (column_id) REFERENCES columns(id) ON DELETE CASCADE
    );
  `;
}

// Seed initial column data
async function seedInitialData() {
  const columns = [
    { id: 'todo', title: 'To Do', position: 0 },
    { id: 'in-progress', title: 'In Progress', position: 1 },
    { id: 'done', title: 'Done', position: 2 }
  ];

  for (const column of columns) {
    const result = await db.sql`
      INSERT INTO columns (id, title, position)
      VALUES (${column.id}, ${column.title}, ${column.position})
      ON CONFLICT (id) DO NOTHING;
    `;
  }
}

// Helper function to broadcast events to all SSE clients
function broadcastEvent(eventType, data) {
  const eventData = JSON.stringify(data);
  sseClients.forEach(client => {
    client.write(`event: ${eventType}\n`);
    client.write(`data: ${eventData}\n\n`);
  });
}

// Helper function to get the next available position in a column
async function getNextPosition(columnId) {
  const result = await db.sql`
    SELECT position FROM cards WHERE column_id = ${columnId} ORDER BY position DESC LIMIT 1;
  `;

  const rows = result.rows;
  if (rows.length === 0) {
    return 1; // First position in the column
  }

  const lastPosition = rows[0].position;

  // Check for position collisions/exhaustion
  if (lastPosition > 1000000) {
    // Renormalize positions if they get too large
    await renormalizePositions(columnId);
    return 1;
  }

  // Use a position between the last one and the one before it (if it exists)
  const prevResult = await db.sql`
    SELECT position FROM cards WHERE column_id = ${columnId} ORDER BY position DESC LIMIT 2 OFFSET 1;
  `;

  const prevRows = prevResult.rows;
  if (prevRows.length === 0) {
    return lastPosition + 1;
  }

  const prevPosition = prevRows[0].position;
  return (prevPosition + lastPosition) / 2;
}

// Helper function to renormalize positions in a column
async function renormalizePositions(columnId) {
  const result = await db.sql`
    SELECT id, position FROM cards WHERE column_id = ${columnId} ORDER BY position ASC;
  `;

  const cards = result.rows;
  for (let i = 0; i < cards.length; i++) {
    await db.sql`
      UPDATE cards 
      SET position = ${i + 1} 
      WHERE id = ${cards[i].id};
    `;
  }

  // Broadcast the updated column
  const updatedColumn = await getColumnWithCards(columnId);
  broadcastEvent('column-update', { column: updatedColumn });

  return cards.length;
}

// Helper function to get a column with its cards
async function getColumnWithCards(columnId) {
  const columnResult = await db.sql`
    SELECT id, title, position FROM columns WHERE id = ${columnId};
  `;

  if (columnResult.rows.length === 0) {
    return null;
  }

  const column = columnResult.rows[0];

  const cardsResult = await db.sql`
    SELECT id, text, position, created_at FROM cards WHERE column_id = ${columnId} ORDER BY position ASC;
  `;

  return { ...column, cards: cardsResult.rows };
}

// API endpoint to get board state
app.get('/api/board', async (req, res) => {
  try {
    const columnsResult = await db.sql`
      SELECT id, title, position 
      FROM columns 
      ORDER BY position ASC;
    `;

    const columns = columnsResult.rows;

    // Get cards for each column, ordered by position
    const columnsWithCards = await Promise.all(
      columns.map(async column => {
        const cardsResult = await db.sql`
          SELECT id, text, position, created_at 
          FROM cards 
          WHERE column_id = ${column.id} 
          ORDER BY position ASC;
        `;
        return {
          ...column,
          cards: cardsResult.rows
        };
      })
    );

    res.json({ columns: columnsWithCards });
  } catch (error) {
    console.error('Error fetching board state:', error);
    res.status(500).json({ error: 'Failed to fetch board state' });
  }
});

// API endpoint to create a new card
app.post('/api/cards', async (req, res) => {
  try {
    const { columnId, text } = req.body;

    if (!columnId || !text) {
      return res.status(400).json({ error: 'columnId and text are required' });
    }

    // Start transaction
    await db.begin();

    try {
      // Get next position for the column
      const position = await getNextPosition(columnId);

      // Create the card
      const cardId = uuidv4();
      await db.sql`
        INSERT INTO cards (id, column_id, text, position)
        VALUES (${cardId}, ${columnId}, ${text}, ${position});
      `;

      // Commit transaction
      await db.commit();

      // Get the full column with the new card
      const column = await getColumnWithCards(columnId);

      // Broadcast the update
      broadcastEvent('card-created', { cardId, columnId, column });

      // Return the created card
      res.status(201).json({ id: cardId, columnId, text, position });
    } catch (error) {
      // Rollback transaction on error
      await db.rollback();
      throw error;
    }
  } catch (error) {
    console.error('Error creating card:', error);
    res.status(500).json({ error: 'Failed to create card' });
  }
});

// API endpoint to move a card
app.patch('/api/cards/:id/move', async (req, res) => {
  try {
    const cardId = req.params.id;
    const { columnId, beforeId, afterId } = req.body;

    if (!columnId) {
      return res.status(400).json({ error: 'columnId is required' });
    }

    // Start transaction to ensure atomic move
    await db.begin();

    try {
      // Get the current card
      const cardResult = await db.sql`
        SELECT column_id, position FROM cards WHERE id = ${cardId};
      `;

      if (cardResult.rows.length === 0) {
        await db.rollback();
        return res.status(404).json({ error: 'Card not found' });
      }

      const currentCard = cardResult.rows[0];

      // If moving to the same column and no position change, do nothing
      if (currentCard.column_id === columnId && (!beforeId && !afterId)) {
        await db.rollback();
        return res.json(currentCard);
      }

      let position;

      // Calculate new position
      if (beforeId && afterId) {
        // Between two cards
        const beforeResult = await db.sql`
          SELECT position FROM cards WHERE id = ${beforeId} AND column_id = ${columnId};
        `;
        const afterResult = await db.sql`
          SELECT position FROM cards WHERE id = ${afterId} AND column_id = ${columnId};
        `;

        if (beforeResult.rows.length === 0 || afterResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'Before or after card not found in target column' });
        }

        position = (beforeResult.rows[0].position + afterResult.rows[0].position) / 2;
      } else if (beforeId) {
        // Before a specific card
        const beforeResult = await db.sql`
          SELECT position FROM cards WHERE id = ${beforeId} AND column_id = ${columnId};
        `;

        if (beforeResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'Before card not found in target column' });
        }

        position = beforeResult.rows[0].position - 0.1;
      } else if (afterId) {
        // After a specific card
        const afterResult = await db.sql`
          SELECT position FROM cards WHERE id = ${afterId} AND column_id = ${columnId};
        `;

        if (afterResult.rows.length === 0) {
          await db.rollback();
          return res.status(400).json({ error: 'After card not found in target column' });
        }

        position = afterResult.rows[0].position + 0.1;
      } else {
        // End of the column
        position = await getNextPosition(columnId);
      }

      // Remove card from source column if different
      if (currentCard.column_id !== columnId) {
        await db.sql`
          DELETE FROM cards WHERE id = ${cardId};
        `;
      }

      // Add card to target column
      await db.sql`
        INSERT INTO cards (id, column_id, text, position)
        VALUES (${cardId}, ${columnId}, ${currentCard.text}, ${position})
        ON CONFLICT (id) DO UPDATE SET column_id = ${columnId}, position = ${position};
      `;

      // Commit transaction
      await db.commit();

      // Get the updated card
      const updatedCardResult = await db.sql`
        SELECT id, column_id, text, position FROM cards WHERE id = ${cardId};
      `;

      const updatedCard = updatedCardResult.rows[0];

      // Get the source and target columns to broadcast
      const sourceColumn = currentCard.column_id !== columnId 
        ? await getColumnWithCards(currentCard.column_id) 
        : null;

      const targetColumn = await getColumnWithCards(columnId);

      // Broadcast the move
      broadcastEvent('card-moved', { 
        cardId, 
        sourceColumnId: currentCard.column_id, 
        targetColumnId: columnId,
        sourceColumn,
        targetColumn
      });

      // Return the updated card
      res.json(updatedCard);
    } catch (error) {
      // Rollback transaction on error
      await db.rollback();
      throw error;
    }
  } catch (error) {
    console.error('Error moving card:', error);
    res.status(500).json({ error: 'Failed to move card' });
  }
});

// SSE endpoint to stream updates
app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  // Send initial heartbeat to keep connection alive
  const heartbeatInterval = setInterval(() => {
    res.write(':\n\n');
  }, 30000);

  // Add client to the set
  sseClients.add(res);

  // Handle client disconnect
  req.on('close', () => {
    clearInterval(heartbeatInterval);
    sseClients.delete(res);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
initDB().then(() => {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Frontend available at http://localhost:${PORT}`);
  });
});"}

